using System.Text.Json;
using System.Text.Json.Nodes;

namespace backend.Services;

public interface ISettingsService
{
    List<string> GetKnownRoomTypes();
    void         SetKnownRoomTypes(List<string> names);
    List<string> GetKnownCategories();
    void         SetKnownCategories(List<string> categories);
    List<string> GetKnownMaterials();
    void         SetKnownMaterials(List<string> materials);
}

public class SettingsService : ISettingsService
{
    private readonly string _path;
    private readonly SemaphoreSlim _lock = new(1, 1);

    private static readonly List<string> DefaultRoomTypes =
    [
        "Bedroom", "Kitchen", "Bathroom", "LivingRoom", "Office",
        "Storage", "Hallway", "Garage", "Bar", "Restaurant"
    ];

    private static readonly List<string> DefaultCategories =
    [
        "Beds", "Bedtable", "Cabinet", "Mirror", "Walldecoration",
        "Chair", "Sofa", "Table", "DiningChair", "Shelf",
        "Lamp", "Plant", "Decoration", "Appliance", "Storage"
    ];

    private static readonly List<string> DefaultMaterials =
    [
        "Holz", "Metall", "Plastik", "Stein"
    ];

    public SettingsService(IWebHostEnvironment env)
    {
        _path = Path.Combine(env.ContentRootPath, "Data", "settings.json");
    }

    public List<string> GetKnownRoomTypes()  => ReadList("knownRoomTypes",  DefaultRoomTypes);
    public List<string> GetKnownCategories() => ReadList("knownCategories", DefaultCategories);
    public List<string> GetKnownMaterials()  => ReadList("knownMaterials",  DefaultMaterials);

    public void SetKnownRoomTypes(List<string> names)       => WriteList("knownRoomTypes",  names);
    public void SetKnownCategories(List<string> categories) => WriteList("knownCategories", categories);
    public void SetKnownMaterials(List<string> materials)   => WriteList("knownMaterials",  materials);

    private List<string> ReadList(string key, List<string> defaults)
    {
        try
        {
            if (!File.Exists(_path))
            {
                WriteList(key, new(defaults));
                return new(defaults);
            }
            using var doc = JsonDocument.Parse(File.ReadAllText(_path));
            if (doc.RootElement.TryGetProperty(key, out var arr))
            {
                var list = arr.EnumerateArray()
                    .Select(e => e.GetString() ?? "")
                    .Where(s => s.Length > 0)
                    .ToList();
                return list.Count > 0 ? list : new(defaults);
            }
            // Key fehlt in der Datei → Defaults persistieren
            WriteList(key, new(defaults));
        }
        catch { }
        return new(defaults);
    }

    private void WriteList(string key, List<string> values)
    {
        _lock.Wait();
        try
        {
            JsonObject obj = [];
            try
            {
                if (File.Exists(_path))
                    obj = JsonNode.Parse(File.ReadAllText(_path))?.AsObject() ?? [];
            }
            catch { }
            obj[key] = JsonSerializer.SerializeToNode(values);
            Directory.CreateDirectory(Path.GetDirectoryName(_path)!);
            File.WriteAllText(_path, obj.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));
        }
        finally { _lock.Release(); }
    }
}

using System.Text;
using backend.Models;

namespace backend.Services;

public interface ITbxExportService
{
    /// <summary>
    /// Reconstructs a TBX XML string from a Building + new furniture placements.
    /// Original structure (tile_entries, rooms, doors/windows/stairs, attributes) is
    /// preserved via TbxMetadata; furniture is written as user_tiles + layer matrices.
    /// </summary>
    string Export(Building building, List<PlacedFurnitureItem> placements);
}

public class TbxExportService : ITbxExportService
{
    // Bekannte Layer in der gewünschten Exportreihenfolge
    private static readonly string[] KnownLayerOrder =
        ["FloorFurniture", "Furniture", "Furniture2", "WallFurniture"];

    public string Export(Building building, List<PlacedFurnitureItem> placements)
    {
        // ── 1. user_tiles-Liste aufbauen (1-basiert, Reihenfolge des Auftretens) ──
        var userTiles   = new List<string>();
        var tileToIndex = new Dictionary<string, int>(StringComparer.Ordinal);

        int GetOrAddIndex(string tileId)
        {
            if (!tileToIndex.TryGetValue(tileId, out var idx))
            {
                userTiles.Add(tileId);
                idx = userTiles.Count; // 1-basiert
                tileToIndex[tileId] = idx;
            }
            return idx;
        }

        // ── 2. Layer-Matrizen aus Placements erzeugen ──────────────────────────
        // TBX-Konvention (aus Referenzdatei abgeleitet):
        //   tile layer-Matrizen: (height+1) Zeilen × (width+1) Spalten
        //   rooms / attributes:   height     Zeilen × width      Spalten
        int layerRows  = building.Height + 1;
        int layerCols  = building.Width  + 1;
        int attribRows = building.Height;
        int attribCols = building.Width;

        var layerMatrices = new Dictionary<int, Dictionary<string, int[][]>>();
        foreach (var floor in building.Floors.OrderBy(f => f.Index))
            layerMatrices[floor.Index] = new Dictionary<string, int[][]>(StringComparer.Ordinal);

        foreach (var p in placements)
        {
            var idx       = GetOrAddIndex(p.TileId);
            var layerName = string.IsNullOrEmpty(p.Layer) ? "Furniture" : p.Layer;

            if (!layerMatrices.TryGetValue(p.FloorIndex, out var floorLayers))
            {
                floorLayers = new Dictionary<string, int[][]>(StringComparer.Ordinal);
                layerMatrices[p.FloorIndex] = floorLayers;
            }

            if (!floorLayers.TryGetValue(layerName, out var matrix))
            {
                matrix = Enumerable.Range(0, layerRows).Select(_ => new int[layerCols]).ToArray();
                floorLayers[layerName] = matrix;
            }

            if (p.Row >= 0 && p.Row < layerRows && p.Col >= 0 && p.Col < layerCols)
                matrix[p.Row][p.Col] = idx;
        }

        // ── 3. XML aufbauen ───────────────────────────────────────────────────
        var sb = new StringBuilder();
        sb.AppendLine("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");

        // <building …> mit stabiler Attributreihenfolge:
        // 1) version (falls vorhanden), 2) width/height, 3) restliche Root-Attribute.
        sb.Append("<building");
        if (building.Tbx.RootAttributes.TryGetValue("version", out var versionVal) && !string.IsNullOrEmpty(versionVal))
            sb.Append($" version=\"{Esc(versionVal)}\"");
        sb.Append($" width=\"{building.Width}\" height=\"{building.Height}\"");
        foreach (var (key, val) in building.Tbx.RootAttributes)
        {
            if (key.Equals("version", StringComparison.OrdinalIgnoreCase)) continue;
            sb.Append($" {key}=\"{Esc(val)}\"");
        }
        sb.AppendLine(">");

        // tile_entry-Blöcke (Original-Reihenfolge erhalten)
        foreach (var block in building.Tbx.TileEntries)
        {
            sb.AppendLine($" <tile_entry category=\"{Esc(block.Category)}\">");
            foreach (var te in block.Tiles)
            {
                var offsetPart = string.IsNullOrEmpty(te.Offset) ? "" : $" offset=\"{Esc(te.Offset)}\"";
                sb.AppendLine($"  <tile enum=\"{Esc(te.Enum)}\" tile=\"{Esc(te.Tile)}\"{offsetPart}/>");
            }
            sb.AppendLine(" </tile_entry>");
        }

        // user_tiles
        if (userTiles.Count > 0)
        {
            sb.AppendLine(" <user_tiles>");
            foreach (var t in userTiles)
                sb.AppendLine($"  <tile tile=\"{Esc(t)}\"/>");
            sb.AppendLine(" </user_tiles>");
        }
        else
        {
            sb.AppendLine(" <user_tiles/>");
        }

        // used_tiles (Originalwerte unverändert)
        if (building.Tbx.UsedTiles.Count > 0)
            sb.AppendLine($" <used_tiles>{string.Join(" ", building.Tbx.UsedTiles)}</used_tiles>");

        // used_furniture
        sb.AppendLine($" <used_furniture>{Esc(building.Tbx.UsedFurnitureRaw)}</used_furniture>");

        // room-Definitionen
        foreach (var room in building.Rooms)
        {
            sb.AppendLine(
                $" <room Name=\"{Esc(room.Name)}\" InternalName=\"{Esc(room.InternalName)}\"" +
                $" Color=\"{Esc(room.Color)}\"" +
                $" InteriorWall=\"{room.InteriorWall}\" InteriorWallTrim=\"{room.InteriorWallTrim}\"" +
                $" Floor=\"{room.FloorTile}\" GrimeFloor=\"{room.GrimeFloor}\"" +
                $" GrimeWall=\"{room.GrimeWall}\" Ceiling=\"{room.Ceiling}\"/>");
        }

        // floors
        foreach (var floor in building.Floors.OrderBy(f => f.Index))
        {
            sb.AppendLine(" <floor>");

            // Objects (doors, windows, stairs, …)
            // RawAttributes ZUERST ausgeben (Original hat z.B. FrameTile vor x)
            foreach (var obj in floor.Objects)
            {
                var typeStr = !string.IsNullOrEmpty(obj.OriginalType)
                    ? obj.OriginalType
                    : obj.Type switch
                    {
                        FloorObjectType.Door   => "door",
                        FloorObjectType.Window => "window",
                        FloorObjectType.Stairs => "stairs",
                        _                      => "furniture",
                    };

                sb.Append($"  <object type=\"{typeStr}\"");
                foreach (var (k, v) in obj.RawAttributes)
                    sb.Append($" {k}=\"{Esc(v)}\"");
                sb.Append($" x=\"{obj.X}\" y=\"{obj.Y}\" dir=\"{obj.Dir}\" Tile=\"{Esc(obj.Tile)}\"");
                sb.AppendLine("/>");
            }

            // rooms-Grid
            sb.AppendLine("  <rooms>");
            for (int i = 0; i < floor.RoomGrid.Length; i++)
                sb.AppendLine(FormatMatrixRow(floor.RoomGrid[i], i < floor.RoomGrid.Length - 1));
            sb.AppendLine("  </rooms>");

            // attributes-Grid: importierten Wert exakt übernehmen;
            // Fallback = leere height × width Matrix
            var attribGrid = floor.AttributesGrid.Length > 0
                ? floor.AttributesGrid
                : Enumerable.Range(0, attribRows).Select(_ => new int[attribCols]).ToArray();
            sb.AppendLine("  <attributes>");
            for (int i = 0; i < attribGrid.Length; i++)
                sb.AppendLine(FormatMatrixRow(attribGrid[i], i < attribGrid.Length - 1));
            sb.AppendLine("  </attributes>");

            // Möbel-Layer-Matrizen (nur belegte Layer ausgeben)
            layerMatrices.TryGetValue(floor.Index, out var floorLayers2);
            floorLayers2 ??= [];

            var layerNames = KnownLayerOrder
                .Concat(floorLayers2.Keys.Where(k => !KnownLayerOrder.Contains(k)))
                .Where(floorLayers2.ContainsKey);

            foreach (var layerName in layerNames)
            {
                var matrix = floorLayers2[layerName];
                sb.AppendLine($"  <tiles layer=\"{layerName}\">");
                for (int i = 0; i < matrix.Length; i++)
                    sb.AppendLine(FormatMatrixRow(matrix[i], i < matrix.Length - 1));
                sb.AppendLine("  </tiles>");
            }

            sb.AppendLine(" </floor>");
        }

        sb.AppendLine("</building>");
        return sb.ToString();
    }

    private static string Esc(string s) =>
        s.Replace("&", "&amp;")
         .Replace("\"", "&quot;")
         .Replace("<", "&lt;")
         .Replace(">", "&gt;");

    private static string FormatMatrixRow(int[] row, bool includeTrailingComma) =>
        includeTrailingComma ? string.Join(",", row) + "," : string.Join(",", row);
}

using System.Xml.Linq;
using backend.Models;

namespace backend.Services;

public interface ITbxParserService
{
    Building Parse(Stream stream);
}

public class TbxParserService : ITbxParserService
{
    public Building Parse(Stream stream)
    {
        var doc = XDocument.Load(stream);
        var root = doc.Root ?? throw new InvalidDataException("Invalid TBX file: no root element.");

        var building = new Building
        {
            Width  = int.Parse(root.Attribute("width")?.Value  ?? "0"),
            Height = int.Parse(root.Attribute("height")?.Value ?? "0"),
        };

        // Parse rooms (order matters — index 1 = first room element)
        foreach (var roomEl in root.Elements("room"))
        {
            building.Rooms.Add(new Room
            {
                Name            = roomEl.Attribute("Name")?.Value            ?? string.Empty,
                InternalName    = roomEl.Attribute("InternalName")?.Value    ?? string.Empty,
                Color           = roomEl.Attribute("Color")?.Value           ?? "128 128 128",
                InteriorWall    = ParseInt(roomEl.Attribute("InteriorWall")?.Value),
                InteriorWallTrim= ParseInt(roomEl.Attribute("InteriorWallTrim")?.Value),
                FloorTile       = ParseInt(roomEl.Attribute("Floor")?.Value),
                GrimeFloor      = ParseInt(roomEl.Attribute("GrimeFloor")?.Value),
                GrimeWall       = ParseInt(roomEl.Attribute("GrimeWall")?.Value),
                Ceiling         = ParseInt(roomEl.Attribute("Ceiling")?.Value),
            });
        }

        // Parse floors
        int floorIndex = 0;
        foreach (var floorEl in root.Elements("floor"))
        {
            var floor = new Floor { Index = floorIndex++ };

            // Room grid
            var roomsEl = floorEl.Element("rooms");
            if (roomsEl != null)
                floor.RoomGrid = ParseGrid(roomsEl.Value);

            // Objects (doors, windows, stairs, …)
            foreach (var obj in floorEl.Elements("object"))
            {
                var typeStr = obj.Attribute("type")?.Value ?? string.Empty;
                var dirStr  = obj.Attribute("dir")?.Value  ?? "N";

                floor.Objects.Add(new FloorObject
                {
                    Type = typeStr.ToLowerInvariant() switch
                    {
                        "door"    => FloorObjectType.Door,
                        "window"  => FloorObjectType.Window,
                        "stairs"  => FloorObjectType.Stairs,
                        _         => FloorObjectType.Other
                    },
                    X    = ParseInt(obj.Attribute("x")?.Value),
                    Y    = ParseInt(obj.Attribute("y")?.Value),
                    Dir  = Enum.TryParse<Direction>(dirStr, true, out var dir) ? dir : Direction.N,
                    Tile = obj.Attribute("Tile")?.Value ?? string.Empty,
                });
            }

            // Compute WallEdges from doors and windows.
            // Each door/window lives on the shared edge between two adjacent cells,
            // so we store both cell references for the furniture-placement system.
            foreach (var obj in floor.Objects)
            {
                if (obj.Type != FloorObjectType.Door && obj.Type != FloorObjectType.Window)
                    continue;

                // Resolve which canonical edge key and which two cells share it
                bool isHorizontal;
                int edgeCol, edgeRow, c1Col, c1Row, c2Col, c2Row;

                switch (obj.Dir)
                {
                    case Direction.N: // north wall of cell (X,Y) = south wall of cell (X, Y-1)
                        isHorizontal = true;
                        edgeCol = obj.X; edgeRow = obj.Y;
                        c1Col = obj.X; c1Row = obj.Y - 1;   // cell above
                        c2Col = obj.X; c2Row = obj.Y;        // this cell
                        break;
                    case Direction.S: // south wall of (X,Y) = north wall of (X, Y+1)
                        isHorizontal = true;
                        edgeCol = obj.X; edgeRow = obj.Y + 1;
                        c1Col = obj.X; c1Row = obj.Y;
                        c2Col = obj.X; c2Row = obj.Y + 1;
                        break;
                    case Direction.W: // west wall of (X,Y) = east wall of (X-1, Y)
                        isHorizontal = false;
                        edgeCol = obj.X; edgeRow = obj.Y;
                        c1Col = obj.X - 1; c1Row = obj.Y;   // cell to the left
                        c2Col = obj.X;     c2Row = obj.Y;
                        break;
                    case Direction.E: // east wall of (X,Y) = west wall of (X+1, Y)
                        isHorizontal = false;
                        edgeCol = obj.X + 1; edgeRow = obj.Y;
                        c1Col = obj.X;     c1Row = obj.Y;
                        c2Col = obj.X + 1; c2Row = obj.Y;   // cell to the right
                        break;
                    default: continue;
                }

                floor.Edges.Add(new WallEdge
                {
                    EdgeKey      = $"{(isHorizontal ? "H" : "V")}:{edgeCol},{edgeRow}",
                    Type         = obj.Type,
                    IsHorizontal = isHorizontal,
                    EdgeCol      = edgeCol,
                    EdgeRow      = edgeRow,
                    Cell1Col     = c1Col, Cell1Row = c1Row,
                    Cell2Col     = c2Col, Cell2Row = c2Row,
                });
            }

            building.Floors.Add(floor);
        }

        // ── Stair waypoints (computed once here, stored per floor) ─────────────
        const int StairSpan = 5;
        for (int fi = 0; fi < building.Floors.Count; fi++)
        {
            var fl = building.Floors[fi];
            foreach (var obj in fl.Objects)
            {
                if (obj.Type != FloorObjectType.Stairs) continue;

                // Ascending entry = LAST cell of span on this floor
                int ei    = StairSpan - 1;
                int acCol = obj.Dir == Direction.W ? obj.X + ei : obj.X;
                int acRow = obj.Dir == Direction.N ? obj.Y + ei : obj.Y;
                fl.StairWaypoints.Add(new StairWaypoint
                {
                    Col = acCol, Row = acRow,
                    WaypointType = StairWaypointType.Ascending
                });

                // Descending entry = FIRST cell of span on the floor ABOVE
                if (fi + 1 < building.Floors.Count)
                    building.Floors[fi + 1].StairWaypoints.Add(new StairWaypoint
                    {
                        Col = obj.X, Row = obj.Y,
                        WaypointType = StairWaypointType.Descending
                    });
            }
        }

        return building;
    }

    // -----------------------------------------------------------------------

    private static int[][] ParseGrid(string raw)
    {
        var rows = raw
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(l => l.Length > 0)
            .Select(line =>
                line.Split(',', StringSplitOptions.TrimEntries)
                    .Where(v => v.Length > 0)
                    .Select(v => int.TryParse(v, out var n) ? n : 0)
                    .ToArray()
            )
            .ToArray();
        return rows;
    }

    private static int ParseInt(string? value) =>
        int.TryParse(value, out var n) ? n : 0;
}

using System.Xml.Linq;
using backend.Models;

namespace backend.Services;

public interface ITbxParserService
{
    Building Parse(Stream stream);
}

public class TbxParserService : ITbxParserService
{
    public Building Parse(Stream stream)
    {
        var doc = XDocument.Load(stream);
        var root = doc.Root ?? throw new InvalidDataException("Invalid TBX file: no root element.");

        var building = new Building
        {
            Width  = int.Parse(root.Attribute("width")?.Value  ?? "0"),
            Height = int.Parse(root.Attribute("height")?.Value ?? "0"),
        };

        // ── TBX Roundtrip-Metadaten ───────────────────────────────────────────

        // Root-Attribute außer width/height in TbxMetadata übernehmen
        foreach (var attr in root.Attributes())
        {
            if (attr.Name.LocalName is "width" or "height") continue;
            building.Tbx.RootAttributes[attr.Name.LocalName] = attr.Value;
        }

        // tile_entry-Blöcke (Reihenfolge beibehalten – "floors" kommt mehrfach)
        foreach (var entryEl in root.Elements("tile_entry"))
        {
            var block = new TbxTileEntryBlock
            {
                Category = entryEl.Attribute("category")?.Value ?? string.Empty,
            };
            foreach (var tileEl in entryEl.Elements("tile"))
            {
                block.Tiles.Add(new TbxTileEntry
                {
                    Enum   = tileEl.Attribute("enum")?.Value   ?? string.Empty,
                    Tile   = tileEl.Attribute("tile")?.Value   ?? string.Empty,
                    Offset = tileEl.Attribute("offset")?.Value ?? string.Empty,
                });
            }
            building.Tbx.TileEntries.Add(block);
        }

        // user_tiles – geordnete Möbel-Tile-Liste (1-basierter Index durch Listenposition)
        var userTilesEl = root.Element("user_tiles");
        if (userTilesEl != null)
        {
            foreach (var tileEl in userTilesEl.Elements("tile"))
            {
                var tileName = tileEl.Attribute("tile")?.Value ?? string.Empty;
                if (!string.IsNullOrEmpty(tileName))
                    building.Tbx.UserTiles.Add(tileName);
            }
        }

        // used_tiles – Raum-/Basisstruktur-Indizes
        var usedTilesEl = root.Element("used_tiles");
        if (usedTilesEl != null)
        {
            building.Tbx.UsedTiles = (usedTilesEl.Value ?? string.Empty)
                .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Select(v => int.TryParse(v, out var n) ? n : -1)
                .Where(n => n >= 0)
                .ToList();
        }

        // used_furniture – aktuell roh beibehalten
        var usedFurnitureEl = root.Element("used_furniture");
        if (usedFurnitureEl != null)
            building.Tbx.UsedFurnitureRaw = usedFurnitureEl.Value ?? string.Empty;

        // Parse rooms (order matters — index 1 = first room element)
        foreach (var roomEl in root.Elements("room"))
        {
            building.Rooms.Add(new Room
            {
                Name            = roomEl.Attribute("Name")?.Value            ?? string.Empty,
                InternalName    = roomEl.Attribute("InternalName")?.Value    ?? string.Empty,
                Color           = roomEl.Attribute("Color")?.Value           ?? "128 128 128",
                InteriorWall    = ParseInt(roomEl.Attribute("InteriorWall")?.Value),
                InteriorWallTrim= ParseInt(roomEl.Attribute("InteriorWallTrim")?.Value),
                FloorTile       = ParseInt(roomEl.Attribute("Floor")?.Value),
                GrimeFloor      = ParseInt(roomEl.Attribute("GrimeFloor")?.Value),
                GrimeWall       = ParseInt(roomEl.Attribute("GrimeWall")?.Value),
                Ceiling         = ParseInt(roomEl.Attribute("Ceiling")?.Value),
            });
        }

        // Parse floors
        int floorIndex = 0;
        foreach (var floorEl in root.Elements("floor"))
        {
            var floor = new Floor { Index = floorIndex++ };

            // Room grid
            var roomsEl = floorEl.Element("rooms");
            if (roomsEl != null)
                floor.RoomGrid = ParseGrid(roomsEl.Value);

            // Attributes grid (optional – leer = alles 0)
            var attribEl = floorEl.Element("attributes");
            if (attribEl != null)
                floor.AttributesGrid = ParseGrid(attribEl.Value);

            // Tile-Layer-Matrizen (FloorFurniture, Furniture, Furniture2, WallFurniture, …)
            foreach (var layerEl in floorEl.Elements("tiles"))
            {
                var layerName = layerEl.Attribute("layer")?.Value ?? string.Empty;
                if (!string.IsNullOrEmpty(layerName))
                    floor.TileLayers[layerName] = ParseGrid(layerEl.Value);
            }

            // Objects (doors, windows, stairs, …)
            foreach (var obj in floorEl.Elements("object"))
            {
                var typeStr = obj.Attribute("type")?.Value ?? string.Empty;
                var dirStr  = obj.Attribute("dir")?.Value  ?? "N";

                // Bekannte Kernfelder nicht in RawAttributes doppelt ablegen
                var knownAttribs = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                    { "type", "x", "y", "dir", "Tile" };
                var rawAttribs = obj.Attributes()
                    .Where(a => !knownAttribs.Contains(a.Name.LocalName))
                    .ToDictionary(a => a.Name.LocalName, a => a.Value);

                floor.Objects.Add(new FloorObject
                {
                    Type = typeStr.ToLowerInvariant() switch
                    {
                        "door"    => FloorObjectType.Door,
                        "window"  => FloorObjectType.Window,
                        "stairs"  => FloorObjectType.Stairs,
                        _         => FloorObjectType.Other
                    },
                    OriginalType   = typeStr,
                    X              = ParseInt(obj.Attribute("x")?.Value),
                    Y              = ParseInt(obj.Attribute("y")?.Value),
                    Dir            = Enum.TryParse<Direction>(dirStr, true, out var dir) ? dir : Direction.N,
                    Tile           = obj.Attribute("Tile")?.Value ?? string.Empty,
                    RawAttributes  = rawAttribs,
                });
            }

            // Compute WallEdges from doors and windows.
            // Each door/window lives on the shared edge between two adjacent cells,
            // so we store both cell references for the furniture-placement system.
            foreach (var obj in floor.Objects)
            {
                if (obj.Type != FloorObjectType.Door && obj.Type != FloorObjectType.Window)
                    continue;

                // Resolve which canonical edge key and which two cells share it
                bool isHorizontal;
                int edgeCol, edgeRow, c1Col, c1Row, c2Col, c2Row;

                switch (obj.Dir)
                {
                    case Direction.N: // north wall of cell (X,Y) = south wall of cell (X, Y-1)
                        isHorizontal = true;
                        edgeCol = obj.X; edgeRow = obj.Y;
                        c1Col = obj.X; c1Row = obj.Y - 1;   // cell above
                        c2Col = obj.X; c2Row = obj.Y;        // this cell
                        break;
                    case Direction.S: // south wall of (X,Y) = north wall of (X, Y+1)
                        isHorizontal = true;
                        edgeCol = obj.X; edgeRow = obj.Y + 1;
                        c1Col = obj.X; c1Row = obj.Y;
                        c2Col = obj.X; c2Row = obj.Y + 1;
                        break;
                    case Direction.W: // west wall of (X,Y) = east wall of (X-1, Y)
                        isHorizontal = false;
                        edgeCol = obj.X; edgeRow = obj.Y;
                        c1Col = obj.X - 1; c1Row = obj.Y;   // cell to the left
                        c2Col = obj.X;     c2Row = obj.Y;
                        break;
                    case Direction.E: // east wall of (X,Y) = west wall of (X+1, Y)
                        isHorizontal = false;
                        edgeCol = obj.X + 1; edgeRow = obj.Y;
                        c1Col = obj.X;     c1Row = obj.Y;
                        c2Col = obj.X + 1; c2Row = obj.Y;   // cell to the right
                        break;
                    default: continue;
                }

                floor.Edges.Add(new WallEdge
                {
                    EdgeKey      = $"{(isHorizontal ? "H" : "V")}:{edgeCol},{edgeRow}",
                    Type         = obj.Type,
                    IsHorizontal = isHorizontal,
                    EdgeCol      = edgeCol,
                    EdgeRow      = edgeRow,
                    Cell1Col     = c1Col, Cell1Row = c1Row,
                    Cell2Col     = c2Col, Cell2Row = c2Row,
                });
            }

            building.Floors.Add(floor);
        }

        // ── Stair waypoints (computed once here, stored per floor) ─────────────
        const int StairSpan = 5;
        for (int fi = 0; fi < building.Floors.Count; fi++)
        {
            var fl = building.Floors[fi];
            foreach (var obj in fl.Objects)
            {
                if (obj.Type != FloorObjectType.Stairs) continue;

                // Ascending entry = LAST cell of span on this floor
                int ei    = StairSpan - 1;
                int acCol = obj.Dir == Direction.W ? obj.X + ei : obj.X;
                int acRow = obj.Dir == Direction.N ? obj.Y + ei : obj.Y;
                fl.StairWaypoints.Add(new StairWaypoint
                {
                    Col = acCol, Row = acRow,
                    WaypointType = StairWaypointType.Ascending
                });

                // Descending entry = FIRST cell of span on the floor ABOVE
                if (fi + 1 < building.Floors.Count)
                    building.Floors[fi + 1].StairWaypoints.Add(new StairWaypoint
                    {
                        Col = obj.X, Row = obj.Y,
                        WaypointType = StairWaypointType.Descending
                    });
            }
        }

        return building;
    }

    // -----------------------------------------------------------------------

    private static int[][] ParseGrid(string raw)
    {
        var rows = raw
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(l => l.Length > 0)
            .Select(line =>
                line.Split(',', StringSplitOptions.TrimEntries)
                    .Where(v => v.Length > 0)
                    .Select(v => int.TryParse(v, out var n) ? n : 0)
                    .ToArray()
            )
            .ToArray();
        return rows;
    }

    private static int ParseInt(string? value) =>
        int.TryParse(value, out var n) ? n : 0;
}

:root {
  color-scheme: dark;
  font-family: 'Segoe UI', system-ui, sans-serif;
  font-size: 16px;
  background: #0e0e18;
  color: #e0e0f0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.app {
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
/* Vollbild-Tab (Tile-Browser, Moebel-Vorlagen) */
.tab-full {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.app-header {
  padding: 16px 32px;
  border-bottom: 1px solid #2a2a3a;
  background: #12121e;
}

.app-header-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.app-header h1 {
  font-size: 1.6rem;
  font-weight: 700;
  color: #c8a8ff;
}

.app-subtitle {
  font-size: 0.85rem;
  color: #778;
  margin-top: 4px;
}

.lang-switcher {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
  margin-top: 4px;
}

.lang-btn {
  padding: 4px 12px;
  border: 1px solid #3a3a5a;
  border-radius: 5px;
