const BASE = '/api/settings';

async function checkResponse(r: Response, label: string): Promise<void> {
  if (!r.ok) {
    const text = await r.text().catch(() => '');
    throw new Error(
      text
        ? `${label}: ${text}`
        : `${label}: Backend antwortet mit Status ${r.status} – ist das Backend gestartet?`,
    );
  }
}

