  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [fileName, setFileName] = useState<string | null>(null);

  const handleFile = async (file: File) => {
    setError(null);
    setLoading(true);
    setFileName(file.name);
    try {
      const building = await uploadTbx(file);
      onBuildingLoaded(building, file.name);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Error');
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) handleFile(file);
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const file = e.dataTransfer.files?.[0];
    if (file) handleFile(file);
  };

  return (
    <div
      className={styles.dropZone}
      onDrop={handleDrop}
      onDragOver={(e) => e.preventDefault()}
      onClick={() => inputRef.current?.click()}
    >
      <input ref={inputRef} type="file" accept=".tbx" className={styles.hidden} onChange={handleChange} />
      {loading ? (
        <p className={styles.hint}>⏳ {t('upload.processing')}</p>
      ) : (
        <>
          <p className={styles.icon}></p>
          <p className={styles.hint}>
            {fileName ? t('upload.loaded', { name: fileName }) : t('upload.hint')}
          </p>
        </>
      )}
      {error && <p className={styles.error}>❌ {error}</p>}
    </div>
  );
}

.panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px;
  background: #0a0a14;
  border-left: 1px solid #2a2a3a;
  width: 280px;
  flex-shrink: 0;
  overflow-y: auto;
}

.panelTitle {
  font-size: 0.8rem;
  font-weight: 700;
  color: #c8a8ff;
  margin: 0 0 4px;
}

.sectionLabel {
  font-size: 0.68rem;
  color: #668;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin: 6px 0 4px;
}

/* ── Room list ── */
.roomList {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.roomRow {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: 4px;
  background: #141422;
  border: 1px solid #2a2a3a;
  cursor: pointer;
  user-select: none;
}
.roomRow:hover { background: #1a1a2e; }
.roomRowSelected { border-color: #8866cc; background: #1e1e3a; }

.roomRowCheck {
  accent-color: #8866cc;
  flex-shrink: 0;
}

.roomRowName {
  font-size: 0.76rem;
  color: #ccd;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.roomRowType {
  font-size: 0.66rem;
  color: #778;
  font-style: italic;
}

.roomRowBadge {
  font-size: 0.62rem;
  background: #2a1a4a;
  color: #aa88dd;
  border-radius: 8px;
  padding: 1px 5px;
  flex-shrink: 0;
}

.roomRowNoMatch {
  font-size: 0.62rem;
  color: #f66;
  flex-shrink: 0;
}

/* Color swatch next to room name */
.roomColorSwatch {
  width: 12px;
  height: 12px;
  border-radius: 2px;
  border: 1px solid rgba(255,255,255,0.15);
  flex-shrink: 0;
  display: inline-block;
}

/* Override input for roomType */
.overrideInput {
  width: 100%;
  padding: 3px 6px;
  background: #0e0e18;
  border: 1px solid #3a3a5a;
  border-radius: 3px;
  color: #dde;
  font-size: 0.72rem;
  margin-top: 3px;
}
.overrideInput:focus { outline: none; border-color: #8866cc; }

/* ── Seed row ── */
.seedRow {
  display: flex;
  align-items: center;
  gap: 8px;
}
.seedLabel { font-size: 0.72rem; color: #668; }
.seedInput {
  width: 80px;
  padding: 3px 6px;
  background: #0e0e18;
  border: 1px solid #3a3a5a;
  border-radius: 3px;
  color: #dde;
  font-size: 0.76rem;
  text-align: center;
}
.seedInput:focus { outline: none; border-color: #8866cc; }
.seedRandom {
  padding: 3px 8px;
  background: #1a1a2e;
  border: 1px solid #3a3a5a;
  border-radius: 3px;
  color: #88a;
  cursor: pointer;
  font-size: 0.72rem;
}
.seedRandom:hover { border-color: #8866cc; color: #ddf; }

/* ── Generate button ── */
.generateBtn {
  padding: 8px;
  background: #2a4a2a;
  border: 1px solid #4a9a4a;
  border-radius: 6px;
  color: #9f9;
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 600;
  width: 100%;
}
.generateBtn:hover:not(:disabled) { background: #3a6a3a; }
.generateBtn:disabled { opacity: 0.5; cursor: not-allowed; }

/* ── Export button ── */
.exportBtn {
  padding: 7px;
  background: #1a2a3a;
  border: 1px solid #3a7aaa;
  border-radius: 6px;
  color: #7af;
  cursor: pointer;
  font-size: 0.82rem;
  font-weight: 600;
  width: 100%;
}
.exportBtn:hover:not(:disabled) { background: #2a3a5a; }
.exportBtn:disabled { opacity: 0.5; cursor: not-allowed; }

/* ── Status ── */
.status {
  font-size: 0.72rem;
  text-align: center;
  padding: 4px;
  border-radius: 4px;
}
.statusOk    { color: #6c6; background: #1a2a1a; }
.statusError { color: #f88; background: #2a1a1a; }

/* ── Log ── */
.logToggle {
  font-size: 0.74rem;
  color: #778;
  cursor: pointer;
  background: #0e0e18;
  border: 1px solid #2a2a3a;
  border-radius: 5px;
  padding: 5px 10px;
  text-align: left;
  width: 100%;
  transition: background 0.12s, color 0.12s;
}
.logToggle:hover { background: #141428; color: #aab; border-color: #445; }

.logBox {
  background: #080812;
  border: 1px solid #272736;
  border-radius: 6px;
  padding: 8px 6px;
  max-height: 340px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.logLine {
  font-family: 'Consolas', 'Fira Mono', monospace;
  font-size: 0.78rem;
  line-height: 1.55;
  padding: 1px 6px;
  border-radius: 3px;
  white-space: pre-wrap;
  word-break: break-all;
}

/* Zeilentypen */
.logRoom   { color: #88ccff; background: rgba(40,80,140,0.18); font-weight: 600; }
.logPlaced { color: #77ee88; }
.logSlot   { color: #aabbee; }
.logGroup  { color: #cc99ff; }
.logWarn   { color: #ffaa44; background: rgba(120,60,0,0.22); }
.logSkip   { color: #ff6666; background: rgba(100,20,20,0.18); }
.logOther  { color: #556677; }

/* ── Result summary ── */
.resultSummary {
  font-size: 0.72rem;
  color: #88a;
  background: #141422;
  border: 1px solid #2a2a3a;
  border-radius: 4px;
  padding: 6px 8px;
}

/* InternalName shown next to display name */
.roomInternalName {
  font-size: 0.66rem;
  color: #556;
  font-style: italic;
}

/* ── Density sliders ── */
.densityRow {
  display: flex;
  align-items: center;
  gap: 8px;
}

.densityLabel {
  flex-shrink: 0;
  width: 52px;
  font-size: 0.7rem;
  color: #99aacc;
  text-align: right;
}

.densitySlider {
  flex: 1;
  accent-color: #8866ff;
  cursor: pointer;
}

.densityHint {
  font-size: 0.65rem;
  color: #556;
  margin: 0;
  line-height: 1.4;
}

.densityToggle {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.7rem;
  color: #99aacc;
  cursor: pointer;
  user-select: none;
}

.densityToggle input {
  accent-color: #8866ff;
  cursor: pointer;
}

import { useState, useEffect, useMemo, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import type { Building, PlacedFurnitureItem } from '../../types/building';
import { generateFurnishing, exportTbx } from '../../api/furnishApi';
import type { RoomSelection } from '../../api/furnishApi';
import { getRoomTypes } from '../../api/roomTypesApi';
import s from './FurnishPanel.module.css';

interface Props {
  building: Building;
  fileName: string;
  onPlacementsChanged: (placements: PlacedFurnitureItem[]) => void;
  onLogChanged?: (log: string[]) => void;
}

interface RoomEntry { floorIndex: number; roomIndex1Based: number; }

/** Collect rooms grouped by floor, sorted by floorIndex then roomIndex. */
function collectRoomsByFloor(building: Building): Map<number, RoomEntry[]> {
  const map = new Map<number, RoomEntry[]>();
  for (const floor of building.floors) {
    const seen = new Set<number>();
    for (const row of floor.roomGrid) {
      for (const idx of row) {
        if (idx <= 0 || seen.has(idx)) continue;
        seen.add(idx);
        if (!map.has(floor.index)) map.set(floor.index, []);
        map.get(floor.index)!.push({ floorIndex: floor.index, roomIndex1Based: idx });
      }
    }
  }
  for (const rooms of map.values()) rooms.sort((a, b) => a.roomIndex1Based - b.roomIndex1Based);
  return new Map([...map.entries()].sort((a, b) => a[0] - b[0]));
}

/** Count cells of a room on a floor */
function roomCellCount(building: Building, floorIndex: number, roomIndex1Based: number): number {
  const floor = building.floors.find(f => f.index === floorIndex);
  if (!floor) return 0;
  let n = 0;
  for (const row of floor.roomGrid) for (const idx of row) if (idx === roomIndex1Based) n++;
  return n;
}

const SIZE_LABELS: Record<string, string> = {
  XS: 'XS ≤4', S: 'S ≤12', M: 'M ≤25', L: 'L ≤50', XL: 'XL 50+',
};
function classifySize(cells: number) {
  if (cells <= 4)  return 'XS';
  if (cells <= 12) return 'S';
  if (cells <= 25) return 'M';
  if (cells <= 50) return 'L';
  return 'XL';
}

/** Convert "R G B" TBX color string to CSS rgb(). */
function tbxColorToCss(color: string | undefined): string {
  if (!color) return '#888';
  const parts = color.trim().split(/\s+/);
  if (parts.length === 3) return `rgb(${parts[0]},${parts[1]},${parts[2]})`;
  return '#888';
}

export default function FurnishPanel({ building, fileName, onPlacementsChanged, onLogChanged }: Props) {
  const { t } = useTranslation();
  const [knownTypes, setKnownTypes]     = useState<string[]>([]);
  const [selected, setSelected]         = useState<Set<string>>(new Set());
  const [overrides, setOverrides]       = useState<Record<string, string>>({});
  const [seed, setSeed]                 = useState<number>(() => Math.floor(Math.random() * 999999));
  const [running, setRunning]           = useState(false);
  const [exporting, setExporting]       = useState(false);
  const [status, setStatus]             = useState<{ msg: string; ok: boolean } | null>(null);
  const [placements, setPlacements]     = useState<PlacedFurnitureItem[]>([]);
  const [densityMin, setDensityMin]       = useState<number>(50);
  const [densityMax, setDensityMax]       = useState<number>(100);
  const [densityPerRoom, setDensityPerRoom] = useState<boolean>(false);

  useEffect(() => {
    getRoomTypes().then(cfgs => setKnownTypes(Object.keys(cfgs))).catch(console.error);
  }, []);

  const roomsByFloor  = useMemo(() => collectRoomsByFloor(building), [building]);
  const allRoomsFlat  = useMemo(() => [...roomsByFloor.values()].flat(), [roomsByFloor]);

  const selKey = (floorIndex: number, roomIndex1Based: number) => `${floorIndex}:${roomIndex1Based}`;

  /** Unique internalNames across all rooms, sorted */
  const uniqueTypes = useMemo(() => {
    const types = new Set<string>();
    for (const e of allRoomsFlat) {
      const name = building.rooms[e.roomIndex1Based - 1]?.internalName;
      if (name) types.add(name);
    }
    return [...types].sort();
  }, [allRoomsFlat, building.rooms]);

  const toggleRoom = (key: string) => setSelected(prev => {
    const next = new Set(prev);
    next.has(key) ? next.delete(key) : next.add(key);
    return next;
  });

  const toggleFloor = (floorIndex: number) => {
    const keys = (roomsByFloor.get(floorIndex) ?? []).map(e => selKey(e.floorIndex, e.roomIndex1Based));
    const allSel = keys.every(k => selected.has(k));
    setSelected(prev => {
      const next = new Set(prev);
      if (allSel) keys.forEach(k => next.delete(k));
      else keys.forEach(k => next.add(k));
      return next;
    });
  };

  const toggleByType = (typeName: string) => {
    const keys = allRoomsFlat
      .filter(e => (building.rooms[e.roomIndex1Based - 1]?.internalName ?? '') === typeName)
      .map(e => selKey(e.floorIndex, e.roomIndex1Based));
    const allSel = keys.every(k => selected.has(k));
    setSelected(prev => {
      const next = new Set(prev);
      if (allSel) keys.forEach(k => next.delete(k));
      else keys.forEach(k => next.add(k));
      return next;
    });
  };

  const toggleAll = () => {
    const allKeys = allRoomsFlat.map(e => selKey(e.floorIndex, e.roomIndex1Based));
    const allSel  = allKeys.every(k => selected.has(k));
    setSelected(allSel ? new Set() : new Set(allKeys));
  };

  const floorCheckState = (floorIndex: number): 'all' | 'some' | 'none' => {
    const keys = (roomsByFloor.get(floorIndex) ?? []).map(e => selKey(e.floorIndex, e.roomIndex1Based));
    const n = keys.filter(k => selected.has(k)).length;
    if (n === 0) return 'none';
    if (n === keys.length) return 'all';
    return 'some';
  };

  const typeIsActive = (typeName: string) => {
    const keys = allRoomsFlat
      .filter(e => (building.rooms[e.roomIndex1Based - 1]?.internalName ?? '') === typeName)
      .map(e => selKey(e.floorIndex, e.roomIndex1Based));
    return keys.length > 0 && keys.every(k => selected.has(k));
  };

  const allSel = allRoomsFlat.length > 0 && allRoomsFlat.every(e => selected.has(selKey(e.floorIndex, e.roomIndex1Based)));

  const floorLabel = (floorIndex: number) =>
    floorIndex === 0 ? t('floor.ground') : t('floor.upper', { n: floorIndex });


  const handleGenerate = async () => {
    const selections: RoomSelection[] = [];
    for (const key of selected) {
      const [f, r] = key.split(':').map(Number);
      selections.push({ floorIndex: f, roomIndex1Based: r, roomTypeOverride: overrides[key] ?? '' });
    }
    if (selections.length === 0) { setStatus({ msg: t('furnishPanel.noRoomSelected'), ok: false }); return; }

    setRunning(true); setStatus(null);
    try {
      const result = await generateFurnishing(building, selections, seed, densityMin / 100, densityMax / 100, densityPerRoom);
      setPlacements(result.placements);
      onPlacementsChanged(result.placements);
      onLogChanged?.(result.log);
      setStatus({ msg: t('furnishPanel.tilesPlaced', { tiles: result.placements.length, rooms: selections.length }), ok: true });
    } catch (e) {
      setStatus({ msg: `Fehler: ${String(e)}`, ok: false });
    } finally {
      setRunning(false);
    }
  };

  const handleExport = async () => {
    if (placements.length === 0) return;
    setExporting(true);
    try {
      await exportTbx(building, placements, fileName);
      setStatus({ msg: `✓ ${t('furnishPanel.exportOk')}`, ok: true });
    } catch (e) {
      setStatus({ msg: t('furnishPanel.exportError', { error: String(e) }), ok: false });
    } finally {
      setExporting(false);
    }
  };

  return (
    <div className={s.panel}>
      <p className={s.panelTitle}>{t('furnishPanel.title')}</p>

      {/* ── Quick-select toolbar ── */}
      <span className={s.sectionLabel}>{t('furnishPanel.selectRooms')}</span>
      <div className={s.typeToolbar}>
        <button
          className={`${s.typeBtn} ${allSel ? s.typeBtnActive : ''}`}
          onClick={toggleAll}
          title={allSel ? t('furnishPanel.deselectAll') : t('furnishPanel.selectAll')}
        >
          {t('furnishPanel.selectAll')}
        </button>
        {uniqueTypes.map(typeName => (
          <button
            key={typeName}
            className={`${s.typeBtn} ${typeIsActive(typeName) ? s.typeBtnActive : ''}`}
            onClick={() => toggleByType(typeName)}
            title={typeName}
          >
            {typeName}
          </button>
        ))}
      </div>

      {/* ── Room list grouped by floor ── */}
      <div className={s.roomList}>
        {[...roomsByFloor.entries()].map(([floorIndex, rooms]) => (
          <div key={floorIndex} className={s.floorGroup}>

            {/* Floor header */}
            <div className={s.floorHeader} onClick={() => toggleFloor(floorIndex)}>
              <FloorCheckbox state={floorCheckState(floorIndex)} />
              <span className={s.floorLabel}>{floorLabel(floorIndex)}</span>
              <span className={s.floorRoomCount}>{rooms.length}</span>
            </div>

            {/* Room rows */}
            {rooms.map(({ floorIndex: fi, roomIndex1Based }) => {
              const key         = selKey(fi, roomIndex1Based);
              const room        = building.rooms[roomIndex1Based - 1];
              const cells       = roomCellCount(building, fi, roomIndex1Based);
              const sizeKey     = classifySize(cells);
              const typeName    = overrides[key] || room?.internalName || '';
              const displayName = room?.name || `Raum ${roomIndex1Based}`;
              const hasMatch    = knownTypes.some(k => k.toLowerCase() === typeName.toLowerCase());
              const isSel       = selected.has(key);
              const colorCss    = tbxColorToCss(room?.color);

              return (
                <div key={key}>
                  <div
                    className={`${s.roomRow} ${isSel ? s.roomRowSelected : ''}`}
                    onClick={() => toggleRoom(key)}>
                    <input
                      type="checkbox"
                      className={s.roomRowCheck}
                      checked={isSel}
                      onChange={() => toggleRoom(key)}
                      onClick={e => e.stopPropagation()}
                    />
                    <span
                      className={s.roomColorSwatch}
                      style={{ background: colorCss }}
                      title={`Farbe: ${room?.color}`}
                    />
                    <span className={s.roomRowName} title={`${displayName} (${room?.internalName})`}>
                      {displayName}
                      {room?.internalName && room.internalName !== displayName && (
                        <span className={s.roomInternalName}> · {room.internalName}</span>
                      )}
                    </span>
                    <span className={s.roomRowBadge} title={`${cells} Zellen`}>{SIZE_LABELS[sizeKey]}</span>
                    {!hasMatch && typeName && (
                      <span className={s.roomRowNoMatch} title={`Kein passender Raumtyp für „${typeName}"`}>⚠</span>
                    )}
                  </div>

                  {isSel && (
                    <input
                      className={s.overrideInput}
                      placeholder={`Raumtyp: ${typeName || 'unbekannt'}`}
                      value={overrides[key] ?? ''}
                      list="knownTypesList"
                      onChange={e => setOverrides(prev => ({ ...prev, [key]: e.target.value }))}
                    />
                  )}
                </div>
              );
            })}
          </div>
        ))}
      </div>

      <datalist id="knownTypesList">
        {knownTypes.map(tn => <option key={tn} value={tn} />)}
      </datalist>

      {/* ── Seed ── */}
      <span className={s.sectionLabel}>{t('furnishPanel.seed')}</span>
      <div className={s.seedRow}>
        <span className={s.seedLabel}>{t('furnishPanel.seed')}</span>
        <input
          type="number"
          className={s.seedInput}
          value={seed}
          onChange={e => setSeed(+e.target.value)}
        />
        <button
          className={s.seedRandom}
          onClick={() => setSeed(Math.floor(Math.random() * 999999))}
          title={t('furnishPanel.randomSeed')}>

        </button>
      </div>

      {/* ── Density ── */}
      <span className={s.sectionLabel}>{t('furnishPanel.density')}</span>
      <div className={s.densityRow}>
        <span className={s.densityLabel}>{t('furnishPanel.densityMin')} {densityMin}%</span>
        <input
          type="range" min={0} max={100} step={5}
          value={densityMin}
          className={s.densitySlider}
          onChange={e => {
            const v = +e.target.value;
            setDensityMin(v);
            if (v > densityMax) setDensityMax(v);
          }}
        />
      </div>
      <div className={s.densityRow}>
        <span className={s.densityLabel}>{t('furnishPanel.densityMax')} {densityMax}%</span>
        <input
          type="range" min={0} max={100} step={5}
          value={densityMax}
          className={s.densitySlider}
          onChange={e => {
            const v = +e.target.value;
            setDensityMax(v);
            if (v < densityMin) setDensityMin(v);
          }}
        />
      </div>
      <p className={s.densityHint}>{t('furnishPanel.densityHint', { min: densityMin, max: densityMax })}</p>
      <label className={s.densityToggle}>
        <input
          type="checkbox"
          checked={densityPerRoom}
          onChange={e => setDensityPerRoom(e.target.checked)}
        />
        {t('furnishPanel.densityPerRoom')}
      </label>

      {/* ── Generate ── */}
      <button
        className={s.generateBtn}
        disabled={running || selected.size === 0}
        onClick={handleGenerate}>
        {running
          ? `⏳ ${t('furnishPanel.generating')}`
          : `✨ ${t('furnishPanel.generate', { count: selected.size })}`}
      </button>

      {/* ── Result summary + export ── */}
      {placements.length > 0 && (
        <>
          <div className={s.resultSummary}>
            {t('furnishPanel.tilesPlacedSummary', { count: placements.length })}
          </div>
          <button
            className={s.exportBtn}
            disabled={exporting}
            onClick={handleExport}>
            {exporting ? `⏳ ${t('furnishPanel.exporting')}` : t('furnishPanel.exportTbx')}
          </button>
        </>
      )}

      {/* ── Status ── */}
      {status && (
        <div className={`${s.status} ${status.ok ? s.statusOk : s.statusError}`}>
          {status.msg}
        </div>
      )}
    </div>
  );
}

/** Floor header checkbox – supports indeterminate state */
function FloorCheckbox({ state }: { state: 'all' | 'some' | 'none' }) {
  const ref = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (!ref.current) return;
    ref.current.indeterminate = state === 'some';
    ref.current.checked       = state === 'all';
  }, [state]);
  return (
    <input
      type="checkbox"
      ref={ref}
      className={s.floorCheck}
      onClick={e => e.stopPropagation()}
      readOnly
    />
  );
}

import { useState, useEffect, useMemo, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import type { Building, PlacedFurnitureItem } from '../../types/building';
import { generateFurnishing, exportTbx } from '../../api/furnishApi';
import type { RoomSelection } from '../../api/furnishApi';
import { getRoomTypes } from '../../api/roomTypesApi';
import s from './FurnishPanel.module.css';

interface Props {
  building: Building;
  fileName: string;
  onPlacementsChanged: (placements: PlacedFurnitureItem[]) => void;
  onLogChanged?: (log: string[]) => void;
}

interface RoomEntry {
  floorIndex: number;
  roomIndex1Based: number;
  anchorCol: number;
  anchorRow: number;
  cellCount: number;
  instanceNo: number;
  instanceTotal: number;
}

/** Collect room instances (connected components) grouped by floor. */
function collectRoomsByFloor(building: Building): Map<number, RoomEntry[]> {
  const map = new Map<number, RoomEntry[]>();

  for (const floor of building.floors) {
    const visited = new Set<string>();
    const entries: RoomEntry[] = [];
    const indexCounts = new Map<number, number>();

    const rows = floor.roomGrid.length;
    const cols = floor.roomGrid[0]?.length ?? 0;
    const inBounds = (c: number, r: number) => r >= 0 && r < rows && c >= 0 && c < cols;

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const idx = floor.roomGrid[r]?.[c] ?? 0;
        if (idx <= 0) continue;

        const startKey = `${c},${r}`;
        if (visited.has(startKey)) continue;

        // Flood-fill one connected component for this room index.
        const queue: Array<[number, number]> = [[c, r]];
        visited.add(startKey);
        let cellCount = 0;

        while (queue.length > 0) {
          const [cc, cr] = queue.shift()!;
          cellCount++;
          const neighbors: Array<[number, number]> = [[cc + 1, cr], [cc - 1, cr], [cc, cr + 1], [cc, cr - 1]];
          for (const [nc, nr] of neighbors) {
            if (!inBounds(nc, nr)) continue;
            if ((floor.roomGrid[nr]?.[nc] ?? 0) !== idx) continue;
            const k = `${nc},${nr}`;
            if (visited.has(k)) continue;
            visited.add(k);
            queue.push([nc, nr]);
          }
        }

        indexCounts.set(idx, (indexCounts.get(idx) ?? 0) + 1);
        entries.push({
          floorIndex: floor.index,
          roomIndex1Based: idx,
          anchorCol: c,
          anchorRow: r,
          cellCount,
          instanceNo: 0,
          instanceTotal: 0,
        });
      }
    }

    const runningNo = new Map<number, number>();
    for (const entry of entries) {
      const nextNo = (runningNo.get(entry.roomIndex1Based) ?? 0) + 1;
      runningNo.set(entry.roomIndex1Based, nextNo);
      entry.instanceNo = nextNo;
      entry.instanceTotal = indexCounts.get(entry.roomIndex1Based) ?? 1;
    }

    if (entries.length > 0) map.set(floor.index, entries);
  }

  for (const rooms of map.values()) {
    rooms.sort((a, b) => {
      if (a.roomIndex1Based !== b.roomIndex1Based) return a.roomIndex1Based - b.roomIndex1Based;
      if (a.anchorRow !== b.anchorRow) return a.anchorRow - b.anchorRow;
      return a.anchorCol - b.anchorCol;
    });
  }

  return new Map([...map.entries()].sort((a, b) => a[0] - b[0]));
}


const SIZE_LABELS: Record<string, string> = {
  XS: 'XS ≤4', S: 'S ≤12', M: 'M ≤25', L: 'L ≤50', XL: 'XL 50+',
};
function classifySize(cells: number) {
  if (cells <= 4)  return 'XS';
  if (cells <= 12) return 'S';
  if (cells <= 25) return 'M';
  if (cells <= 50) return 'L';
  return 'XL';
}

/** Convert "R G B" TBX color string to CSS rgb(). */
function tbxColorToCss(color: string | undefined): string {
  if (!color) return '#888';
  const parts = color.trim().split(/\s+/);
  if (parts.length === 3) return `rgb(${parts[0]},${parts[1]},${parts[2]})`;
  return '#888';
}

export default function FurnishPanel({ building, fileName, onPlacementsChanged, onLogChanged }: Props) {
  const { t } = useTranslation();
  const [knownTypes, setKnownTypes]     = useState<string[]>([]);
  const [selected, setSelected]         = useState<Set<string>>(new Set());
  const [overrides, setOverrides]       = useState<Record<string, string>>({});
  const [seed, setSeed]                 = useState<number>(() => Math.floor(Math.random() * 999999));
  const [running, setRunning]           = useState(false);
  const [exporting, setExporting]       = useState(false);
  const [status, setStatus]             = useState<{ msg: string; ok: boolean } | null>(null);
  const [placements, setPlacements]     = useState<PlacedFurnitureItem[]>([]);
  const [densityMin, setDensityMin]       = useState<number>(50);
  const [densityMax, setDensityMax]       = useState<number>(100);
  const [densityPerRoom, setDensityPerRoom] = useState<boolean>(false);

  useEffect(() => {
    getRoomTypes().then(cfgs => setKnownTypes(Object.keys(cfgs))).catch(console.error);
  }, []);

  const roomsByFloor  = useMemo(() => collectRoomsByFloor(building), [building]);
  const allRoomsFlat  = useMemo(() => [...roomsByFloor.values()].flat(), [roomsByFloor]);

  const selKey = (entry: RoomEntry) => `${entry.floorIndex}:${entry.roomIndex1Based}:${entry.anchorCol}:${entry.anchorRow}`;

  /** Unique internalNames across all rooms, sorted */
  const uniqueTypes = useMemo(() => {
    const types = new Set<string>();
    for (const e of allRoomsFlat) {
      const name = building.rooms[e.roomIndex1Based - 1]?.internalName;
      if (name) types.add(name);
    }
    return [...types].sort();
  }, [allRoomsFlat, building.rooms]);

  const toggleRoom = (key: string) => setSelected(prev => {
    const next = new Set(prev);
    next.has(key) ? next.delete(key) : next.add(key);
    return next;
  });

  const toggleFloor = (floorIndex: number) => {
    const keys = (roomsByFloor.get(floorIndex) ?? []).map(selKey);
    const allSel = keys.every(k => selected.has(k));
    setSelected(prev => {
      const next = new Set(prev);
      if (allSel) keys.forEach(k => next.delete(k));
      else keys.forEach(k => next.add(k));
      return next;
    });
  };

  const toggleByType = (typeName: string) => {
    const keys = allRoomsFlat
      .filter(e => (building.rooms[e.roomIndex1Based - 1]?.internalName ?? '') === typeName)
      .map(selKey);
    const allSel = keys.every(k => selected.has(k));
    setSelected(prev => {
      const next = new Set(prev);
      if (allSel) keys.forEach(k => next.delete(k));
      else keys.forEach(k => next.add(k));
      return next;
    });
  };

  const toggleAll = () => {
    const allKeys = allRoomsFlat.map(selKey);
    const allSel  = allKeys.every(k => selected.has(k));
    setSelected(allSel ? new Set() : new Set(allKeys));
  };

  const floorCheckState = (floorIndex: number): 'all' | 'some' | 'none' => {
    const keys = (roomsByFloor.get(floorIndex) ?? []).map(selKey);
    const n = keys.filter(k => selected.has(k)).length;
    if (n === 0) return 'none';
    if (n === keys.length) return 'all';
    return 'some';
  };

  const typeIsActive = (typeName: string) => {
    const keys = allRoomsFlat
      .filter(e => (building.rooms[e.roomIndex1Based - 1]?.internalName ?? '') === typeName)
      .map(selKey);
    return keys.length > 0 && keys.every(k => selected.has(k));
  };

  const allSel = allRoomsFlat.length > 0 && allRoomsFlat.every(e => selected.has(selKey(e)));

  const floorLabel = (floorIndex: number) =>
    floorIndex === 0 ? t('floor.ground') : t('floor.upper', { n: floorIndex });


  const handleGenerate = async () => {
    const selections: RoomSelection[] = [];
    for (const key of selected) {
      const [f, r, c, rr] = key.split(':').map(Number);
      selections.push({
        floorIndex: f,
        roomIndex1Based: r,
        anchorCol: c,
        anchorRow: rr,
        roomTypeOverride: overrides[key] ?? '',
      });
    }
    if (selections.length === 0) { setStatus({ msg: t('furnishPanel.noRoomSelected'), ok: false }); return; }

    setRunning(true); setStatus(null);
    try {
      const result = await generateFurnishing(building, selections, seed, densityMin / 100, densityMax / 100, densityPerRoom);
      setPlacements(result.placements);
      onPlacementsChanged(result.placements);
      onLogChanged?.(result.log);
      setStatus({ msg: t('furnishPanel.tilesPlaced', { tiles: result.placements.length, rooms: selections.length }), ok: true });
    } catch (e) {
      setStatus({ msg: `Fehler: ${String(e)}`, ok: false });
    } finally {
      setRunning(false);
    }
  };

  const handleExport = async () => {
    if (placements.length === 0) return;
    setExporting(true);
    try {
      await exportTbx(building, placements, fileName);
      setStatus({ msg: `✓ ${t('furnishPanel.exportOk')}`, ok: true });
    } catch (e) {
      setStatus({ msg: t('furnishPanel.exportError', { error: String(e) }), ok: false });
    } finally {
      setExporting(false);
    }
  };

  return (
    <div className={s.panel}>
      <p className={s.panelTitle}>{t('furnishPanel.title')}</p>

      {/* ── Quick-select toolbar ── */}
      <span className={s.sectionLabel}>{t('furnishPanel.selectRooms')}</span>
      <div className={s.typeToolbar}>
        <button
          className={`${s.typeBtn} ${allSel ? s.typeBtnActive : ''}`}
          onClick={toggleAll}
          title={allSel ? t('furnishPanel.deselectAll') : t('furnishPanel.selectAll')}
        >
          {t('furnishPanel.selectAll')}
        </button>
        {uniqueTypes.map(typeName => (
          <button
            key={typeName}
            className={`${s.typeBtn} ${typeIsActive(typeName) ? s.typeBtnActive : ''}`}
            onClick={() => toggleByType(typeName)}
            title={typeName}
          >
            {typeName}
          </button>
        ))}
      </div>

      {/* ── Room list grouped by floor ── */}
      <div className={s.roomList}>
        {[...roomsByFloor.entries()].map(([floorIndex, rooms]) => (
          <div key={floorIndex} className={s.floorGroup}>

            {/* Floor header */}
            <div className={s.floorHeader} onClick={() => toggleFloor(floorIndex)}>
              <FloorCheckbox state={floorCheckState(floorIndex)} />
              <span className={s.floorLabel}>{floorLabel(floorIndex)}</span>
              <span className={s.floorRoomCount}>{rooms.length}</span>
            </div>

            {/* Room rows */}
            {rooms.map((entry) => {
              const { roomIndex1Based, cellCount, instanceNo, instanceTotal } = entry;
              const key         = selKey(entry);
              const room        = building.rooms[roomIndex1Based - 1];
              const sizeKey     = classifySize(cellCount);
              const typeName    = overrides[key] || room?.internalName || '';
              const baseName    = room?.name || `Raum ${roomIndex1Based}`;
              const displayName = instanceTotal > 1 ? `${baseName} #${instanceNo}` : baseName;
              const hasMatch    = knownTypes.some(k => k.toLowerCase() === typeName.toLowerCase());
              const isSel       = selected.has(key);
              const colorCss    = tbxColorToCss(room?.color);

              return (
                <div key={key}>
                  <div
                    className={`${s.roomRow} ${isSel ? s.roomRowSelected : ''}`}
                    onClick={() => toggleRoom(key)}>
                    <input
                      type="checkbox"
                      className={s.roomRowCheck}
                      checked={isSel}
                      onChange={() => toggleRoom(key)}
                      onClick={e => e.stopPropagation()}
                    />
                    <span
                      className={s.roomColorSwatch}
                      style={{ background: colorCss }}
                      title={`Farbe: ${room?.color}`}
                    />
                    <span className={s.roomRowName} title={`${displayName} (${room?.internalName}) @ [${entry.anchorCol},${entry.anchorRow}]`}>
                      {displayName}
                      {room?.internalName && room.internalName !== displayName && (
                        <span className={s.roomInternalName}> · {room.internalName}</span>
                      )}
                    </span>
                    <span className={s.roomRowBadge} title={`${cellCount} Zellen`}>{SIZE_LABELS[sizeKey]}</span>
                    {!hasMatch && typeName && (
                      <span className={s.roomRowNoMatch} title={`Kein passender Raumtyp für „${typeName}"`}>⚠</span>
                    )}
                  </div>

                  {isSel && (
                    <input
                      className={s.overrideInput}
                      placeholder={`Raumtyp: ${typeName || 'unbekannt'}`}
                      value={overrides[key] ?? ''}
                      list="knownTypesList"
                      onChange={e => setOverrides(prev => ({ ...prev, [key]: e.target.value }))}
                    />
                  )}
                </div>
              );
            })}
          </div>
        ))}
      </div>

      <datalist id="knownTypesList">
        {knownTypes.map(tn => <option key={tn} value={tn} />)}
      </datalist>

      {/* ── Seed ── */}
      <span className={s.sectionLabel}>{t('furnishPanel.seed')}</span>
      <div className={s.seedRow}>
        <span className={s.seedLabel}>{t('furnishPanel.seed')}</span>
        <input
          type="number"
          className={s.seedInput}
          value={seed}
          onChange={e => setSeed(+e.target.value)}
        />
        <button
          className={s.seedRandom}
          onClick={() => setSeed(Math.floor(Math.random() * 999999))}
          title={t('furnishPanel.randomSeed')}>

        </button>
      </div>

      {/* ── Density ── */}
      <span className={s.sectionLabel}>{t('furnishPanel.density')}</span>
      <div className={s.densityRow}>
        <span className={s.densityLabel}>{t('furnishPanel.densityMin')} {densityMin}%</span>
        <input
          type="range" min={0} max={100} step={5}
          value={densityMin}
          className={s.densitySlider}
          onChange={e => {
            const v = +e.target.value;
            setDensityMin(v);
            if (v > densityMax) setDensityMax(v);
          }}
        />
      </div>
      <div className={s.densityRow}>
        <span className={s.densityLabel}>{t('furnishPanel.densityMax')} {densityMax}%</span>
        <input
          type="range" min={0} max={100} step={5}
          value={densityMax}
          className={s.densitySlider}
          onChange={e => {
            const v = +e.target.value;
            setDensityMax(v);
            if (v < densityMin) setDensityMin(v);
          }}
        />
      </div>
      <p className={s.densityHint}>{t('furnishPanel.densityHint', { min: densityMin, max: densityMax })}</p>
      <label className={s.densityToggle}>
        <input
          type="checkbox"
          checked={densityPerRoom}
          onChange={e => setDensityPerRoom(e.target.checked)}
        />
        {t('furnishPanel.densityPerRoom')}
      </label>

      {/* ── Generate ── */}
      <button
        className={s.generateBtn}
        disabled={running || selected.size === 0}
        onClick={handleGenerate}>
        {running
          ? `⏳ ${t('furnishPanel.generating')}`
          : `✨ ${t('furnishPanel.generate', { count: selected.size })}`}
      </button>

      {/* ── Result summary + export ── */}
      {placements.length > 0 && (
        <>
          <div className={s.resultSummary}>
            {t('furnishPanel.tilesPlacedSummary', { count: placements.length })}
          </div>
          <button
            className={s.exportBtn}
            disabled={exporting}
            onClick={handleExport}>
            {exporting ? `⏳ ${t('furnishPanel.exporting')}` : t('furnishPanel.exportTbx')}
          </button>
        </>
      )}

      {/* ── Status ── */}
      {status && (
        <div className={`${s.status} ${status.ok ? s.statusOk : s.statusError}`}>
          {status.msg}
        </div>
      )}
    </div>
  );
}

/** Floor header checkbox – supports indeterminate state */
function FloorCheckbox({ state }: { state: 'all' | 'some' | 'none' }) {
  const ref = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (!ref.current) return;
    ref.current.indeterminate = state === 'some';
    ref.current.checked       = state === 'all';
  }, [state]);
  return (
    <input
      type="checkbox"
      ref={ref}
      className={s.floorCheck}
      onClick={e => e.stopPropagation()}
      readOnly
    />
  );
}

.layout {
  display: grid;
  grid-template-columns: 220px 1fr 300px;
  grid-template-rows: auto 1fr;
  height: calc(100vh - 68px);
  overflow: hidden;
