  gap: 6px;
}
.groupItem:hover { background: #1a1a2e; }
.groupItemActive { background: #1e1e3a; border-left-color: #8866cc; color: #ddf; }
.groupName { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; }
.groupBadge {
  font-size: 0.68rem;
  background: #2a1a4a;
  color: #aa88dd;
  border-radius: 10px;
  padding: 1px 6px;
  flex-shrink: 0;
}

/* ── Piece panel ── */
.piecePanel {
  display: flex;
  flex-direction: column;
  background: #0a0a14;
  border-right: 1px solid #2a2a3a;
  overflow: hidden;
  min-height: 0;
}
.pieceList {
  overflow-y: auto;
  flex: 1;
  padding: 8px;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  align-content: flex-start;
  gap: 8px;
}
.pieceBlock {
  flex-shrink: 0;
  background: #141422;
  border: 1px solid #2a2a4a;
  border-radius: 6px;
  padding: 6px 6px 4px;
}
.pieceLayer {
  font-size: 0.62rem;
  color: #8866cc;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 4px;
  padding-left: 2px;
  white-space: nowrap;
}
.entryList {
  display: grid;
  grid-template-columns: repeat(2, auto);
  gap: 3px;
}
.entryCard {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 5px;
  background: #141422;
  border: 1px solid #2a2a3a;
  border-radius: 5px;
  cursor: pointer;
  transition: border-color 0.1s;
}
.entryCard:hover      { border-color: #6644aa; background: #1e1e3a; }
.entryCardActive      { border-color: #8866cc !important; background: #1e1e3a; }
.miniLayout {
  display: grid;
  gap: 1px;
}
.miniCell {
  background: #0e0e18;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 2px;
}
.miniCellEmpty { background: #0a0a10; }
.entryMeta {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
  justify-content: space-between;
}
.entryOrient {
  font-size: 0.65rem;
  font-weight: 700;
  color: #8866cc;
  background: #1e1230;
  border-radius: 3px;
  padding: 0 3px;
}
.entryDims {
  font-size: 0.6rem;
  color: #556;
}
.entryRoot {
  font-size: 0.58rem;
  color: #667;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 70px;
  flex: 1;
  text-align: right;
}
.importedBadge {
  font-size: 0.65rem;
  color: #6c6;
}

/* ── Config panel ── */
.configPanel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  background: #0e0e18;
  overflow-y: auto;
  font-size: 0.82rem;
  color: #ccd;
  min-height: 0;
}
.cfgHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.cfgTileId {
  font-size: 0.72rem;
  color: #88aacc;
  word-break: break-all;
}
.alreadyImported {
  font-size: 0.68rem;
  color: #6c6;
  background: #0a2010;
  border: 1px solid #2a5a2a;
  border-radius: 4px;
  padding: 1px 6px;
}
.cfgLayoutPreview {
  background: #141422;
  border: 1px solid #2a2a3a;
  border-radius: 6px;
  padding: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}
.cfgLayoutDims {
  font-size: 0.68rem;
  color: #556;
  margin: 0;
}
.cfgCell {
  background: #0e0e18;
  border: 1px solid #2a2a3a;
  border-radius: 2px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.cfgCellEmptyBox {
  background: #0a0a12;
  border-style: dashed;
}
.cfgCellEmpty {
  font-size: 0.55rem;
  color: #334;
}
/* Wrapper: icon + name stacked */
.cfgCellWrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  cursor: default;
}
.cfgCellName {
  font-size: 0.56rem;
  color: #7799bb;
  word-break: break-all;
  text-align: center;
  line-height: 1.3;
  max-width: 100%;
  overflow-wrap: anywhere;
}
.cfgCellNameEmpty {
  color: #334;
  font-style: italic;
}

/* Sprite list */
.spritesCount {
  font-size: 0.68rem;
  color: #556;
  text-transform: none;
  font-weight: normal;
  letter-spacing: 0;
}
.spritesList {
  display: flex;
  flex-direction: column;
  gap: 3px;
  background: #0a0a14;
  border: 1px solid #1e1e2e;
  border-radius: 5px;
  padding: 6px;
  max-height: 240px;
  overflow-y: auto;
  flex-shrink: 0;
}
.spriteEntry {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 4px;
  border-radius: 3px;
  cursor: default;
}
.spriteEntry:hover { background: #141422; }
.spriteEntryIcon {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 23px;
  height: 46px;
  background: #0e0e18;
  border: 1px solid #1e1e2e;
  border-radius: 2px;
  overflow: hidden;
}
.spriteEntryId {
  font-size: 0.72rem;
  color: #aac;
  font-family: monospace;
  word-break: break-all;
  line-height: 1.4;
  user-select: text;
}
.sectionTitle {
  font-size: 0.7rem;
  color: #668;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-bottom: 1px solid #2a2a3a;
  padding-bottom: 3px;
  margin-top: 4px;
  display: flex;
  align-items: baseline;
  gap: 4px;
}
.fieldRow {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 5px;
}
.fieldLabel { color: #99a; flex-shrink: 0; min-width: 88px; }
.fieldInput, .fieldSelect {
  flex: 1;
  padding: 4px 7px;
  background: #141422;
  border: 1px solid #3a3a5a;
  border-radius: 4px;
  color: #dde;
  font-size: 0.8rem;
  min-width: 0;
}
.fieldInput:focus, .fieldSelect:focus { outline: none; border-color: #8866cc; }
.checkRow {
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  user-select: none;
  margin-top: 4px;
}
.checkRow input { accent-color: #8866cc; }
textarea.fieldInput {
  resize: vertical;
  min-height: 40px;
  max-height: 200px;
}
.saveBtn {
  width: 100%;
  padding: 8px;
  background: #2a4a2a;
  border: 1px solid #4a9a4a;
  border-radius: 6px;
  color: #9f9;
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 600;
}

/* Aufklappbarer Abschnitts-Toggle */
.collapsibleHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  user-select: none;
}
.collapsibleHeader:hover .collapseToggle { color: #aac; }
.collapseToggle {
  font-size: 0.75rem;
  color: #556;
  transition: transform 0.15s;
}
.collapseToggleOpen { transform: rotate(90deg); }
.saveBtn:hover:not(:disabled) { background: #3a6a3a; }
.saveBtn:disabled { opacity: 0.5; cursor: not-allowed; }
.saveHint {
  font-size: 0.7rem;
  color: #446;
  text-align: center;
  margin: 0;
}
.saveHint em { font-style: normal; color: #669; }

/* ── Chip toggles (colors / roomTypes / styleTags) ── */
.chipGroup {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}
.chip {
  padding: 3px 8px;
  border-radius: 12px;
  border: 1px solid #3a3a5a;
  background: #141422;
  color: #889;
  font-size: 0.72rem;
  cursor: pointer;
  user-select: none;
  transition: border-color 0.1s, background 0.1s, color 0.1s;
}
.chip:hover       { border-color: #7755bb; color: #bbb; }
.chipActive       { border-color: #8866cc; background: #2a1a4a; color: #ddf; }

/* number inputs */
.fieldInputSmall {
  width: 60px;
  padding: 4px 7px;
  background: #141422;
  border: 1px solid #3a3a5a;
  border-radius: 4px;
  color: #dde;
  font-size: 0.8rem;
}
.fieldInputSmall:focus { outline: none; border-color: #8866cc; }
.fieldHint {
  font-size: 0.68rem;
  color: #556;
  margin-left: 4px;
}

.infoIcon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  margin-left: 6px;
  border: 1px solid #445;
  border-radius: 50%;
  color: #889;
  font-size: 0.62rem;
  line-height: 1;
  cursor: help;
  user-select: none;
  transition: color 0.12s ease, border-color 0.12s ease, background 0.12s ease;
}

.infoIcon:hover {
  color: #ddf;
  border-color: #8866cc;
  background: #1e1e3a;
}

/* ── Multi-select & dirty state ── */
.entryCardDirty {
  box-shadow: 0 0 0 1px #664400 inset;
}
.chipPartial {
  border-color: #aa6600 !important;
  background: #1c1200 !important;
  color: #bb8833 !important;
}
.chipPartial:hover { border-color: #cc8800 !important; color: #ddaa44 !important; }

.pieceSubHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 4px;
}
.selCount {
  font-size: 0.68rem;
  font-weight: 600;
  color: #8866cc;
  background: #1e1a2e;
  border-radius: 8px;
  padding: 1px 7px;
}
.dirtyBadge {
  font-size: 0.66rem;
  color: #cc8833;
  background: #1c1200;
  border: 1px solid #664400;
  border-radius: 8px;
  padding: 1px 6px;
}
.dirtyDot {
  font-size: 0.68rem;
  color: #cc8833;
}
.ctrlHint {
  font-size: 0.62rem;
  color: #445;
  font-style: italic;
}
.pendingBadge {
  font-size: 0.68rem;
  color: #cc8833;
  background: #1c1200;
  border: 1px solid #664400;
  border-radius: 8px;
  padding: 1px 7px;
  margin-left: auto;
}

/* ── Outer wrapper ── */
.wrapper {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ── Legend wrapper (legend + clear button) ── */
.legendWrapper {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* ── Legend bar ── */
.legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 14px;
  padding: 10px 16px;
  background: #141422;
  border: 1px solid #2a2a3a;
  border-radius: 8px;
}

.legendDivider {
  width: 1px;
  height: 20px;
  background: #3a3a5a;
  margin: 0 4px;
  flex-shrink: 0;
}

.legendItem {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 0.82rem;
  color: #ccd;
  border-radius: 5px;
  padding: 3px 6px;
  transition: background 0.15s, opacity 0.15s;
  user-select: none;
}

/* Clickable room items */
.legendItemClickable { cursor: pointer; }
.legendItemClickable:hover { background: rgba(255,255,255,0.07); }

/* Selected room */
.legendItemSelected {
  background: rgba(255,255,255,0.13);
  outline: 1px solid rgba(255,255,255,0.35);
  color: #fff;
  font-weight: 600;
}

/* Dimmed room */
.legendItemDimmed { opacity: 0.4; }

/* Square swatch */
.legendSwatch {
  display: inline-block;
  width: 14px;
  height: 14px;
  border-radius: 3px;
  border: 1px solid rgba(255,255,255,0.18);
  flex-shrink: 0;
}

/* Door bar in legend */
.legendDoorBar {
  display: inline-block;
  width: 24px;
  height: 7px;
  background: #d4852a;
  border-radius: 2px;
  border: 1.5px solid #000;
  flex-shrink: 0;
}

/* Window bar in legend */
.legendWindowBar {
  display: inline-block;
  width: 24px;
  height: 5px;
  background: #48c8e8;
  border-radius: 1px;
  border: 1.5px solid #000;
  flex-shrink: 0;
}

/* Stair swatch */
.stairSwatch {
  background:
    repeating-linear-gradient(
      45deg,
      #3a3000,
      #3a3000 3px,
      #e8c83a 3px,
      #e8c83a 6px
    ) !important;
  border-color: #e8c83a88 !important;
}

/* Stair entry X in legend */
.legendEntryX {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  font-size: 0.75rem;
  font-weight: 900;
  color: #000;
  background: #e8c83a;
  border-radius: 3px;
  border: 1px solid rgba(255,255,255,0.25);
  text-shadow:
    -1px -1px 0 #fff,
     1px -1px 0 #fff,
    -1px  1px 0 #fff,
     1px  1px 0 #fff;
  flex-shrink: 0;
}

/* Path swatch in legend */
.legendPathDot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(120,180,255,0.85);
  border: 1.5px solid rgba(0,0,0,0.45);
  flex-shrink: 0;
}

/* ── Regen path button (inside legend room item) ── */
.regenBtn {
  margin-left: auto;
  padding: 1px 5px;
  background: transparent;
  border: 1px solid #446688;
  border-radius: 4px;
  color: #88bbdd;
  font-size: 0.72rem;
  cursor: pointer;
  line-height: 1;
  transition: background 0.12s;
}
.regenBtn:hover:not(:disabled) {
  background: #1e3a52;
  color: #cceeff;
}
.regenBtn:disabled { opacity: 0.5; cursor: default; }

/* ── Path toggle button ── */
.pathToggleBtn {
  padding: 3px 10px;
  background: #1a2a3a;
  border: 1px solid #446688;
  border-radius: 5px;
  color: #88bbdd;
  font-size: 0.78rem;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
  white-space: nowrap;
}
.pathToggleBtn:hover {
  background: #1e3a52;
  border-color: #66aadd;
  color: #cceeff;
}
/* Active state as separate class (CSS Modules-safe) */
.pathToggleActive {
  background: #0d2a42 !important;
  border-color: #4d9fcc !important;
  color: #7fd3ff !important;
}

/* ── Regenerate-path button ── */
.regenBtn {
  padding: 1px 6px;
  background: transparent;
  border: 1px solid #446;
  border-radius: 4px;
  color: #99a;
  font-size: 0.72rem;
  cursor: pointer;
  transition: border-color 0.12s, color 0.12s;
  line-height: 1.4;
}
.regenBtn:hover { border-color: #88b; color: #dde; }
.regenBtn:disabled { opacity: 0.4; cursor: default; }

/* ── Clear selection button ── */
.clearBtn {
  align-self: flex-start;
  padding: 5px 14px;
  background: #3a1a3a;
  border: 1px solid #8844aa;
  border-radius: 6px;
  color: #dda0ff;
  font-size: 0.82rem;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.clearBtn:hover {
  background: #541a74;
  border-color: #bb66ff;
  color: #fff;
}

/* ── Scrollable container ── */
.scrollArea {
  overflow: auto;
  max-width: 100%;
}

/* ── Grid ── */
.grid {
  display: grid;
  gap: 0;
}

/* Every cell */
.cell {
  position: relative;
  box-sizing: border-box;
  border: 1px solid rgba(0, 0, 0, 0.30);
  transition: filter 0.1s, background 0.15s;
  overflow: hidden;
}
.cell:hover {
  filter: brightness(1.25);
  z-index: 4;
  outline: 1px solid rgba(255,255,255,0.4);
}

/* Highlighted (selected room) */
.cellHighlighted {
  box-shadow: inset 0 0 0 2px rgba(255,255,255,0.55);
}

/* Path cell blue tint */
.cellPath {
  outline: 2px solid rgba(80,160,255,0.7) !important;
  outline-offset: -2px;
  background-color: rgba(80,160,255,0.25) !important;
}

.outside {
  background: #0c0c16 !important;
  border-color: #1e1e2e !important;
}

/* ── Staircase stripe overlay ── */
.stairStripe {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(
      45deg,
      transparent,
      transparent 4px,
      rgba(232, 200, 58, 0.35) 4px,
      rgba(232, 200, 58, 0.35) 7px
    );
  z-index: 1;
}

/* ── Stair entry/descent X marker ── */
.stairEntry {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1em;
  font-weight: 900;
  color: #000;
  text-shadow:
    -1px -1px 0 #fff,
     1px -1px 0 #fff,
    -1px  1px 0 #fff,
     1px  1px 0 #fff,
     0    0   3px rgba(255,255,255,0.8);
  pointer-events: none;
  z-index: 2;
  user-select: none;
}

.empty {
  color: #778;
  font-style: italic;
}

